mapper.select:
SELECT ce.id, ce.character_id AS characterId, ce.event_id AS eventId, ce.complete_time AS completeTime, c.name AS characterName, e.name AS eventName, e.category AS category, e.wisdom_bonus AS wisdomBonus, e.force_bonus AS forceBonus, e.social_bonus AS socialBonus, e.agility_bonus AS agilityBonus FROM `character_event` ce LEFT JOIN `char_info` c ON ce.character_id = c.id LEFT JOIN `event` e ON ce.event_id = e.id
AND ce.character_id = #{characterId}
ORDER BY ce.complete_time DESC
